```lilypond
\version "2.24.0"

\header {
  title = "Wedding Arrangement in A Minor"
  subtitle = "8-bar motif arrangement"
  composer = ""
  tagline = ""
}

global = {
  \key a \minor
  \time 4/4
  \tempo "Flowing" 4 = 60
}

melody = \relative c'' {
  \global
  \clef treble

  %% Bar 1 — Am
  c8-3( e-1 g-2 a-1 g-2 e-3 4.)

  %% Bar 2 — Dm
  f8-4 a-1 c'-3 d-2 c-3 a-1 f-4 e-3

  %% Bar 3 — Am / E
  c8-3 e-1 g-2 a-1 b-2 gis-1 e-3 b,-4

  %% Bar 4 — Am / E
  a'8-1 g-2 e-3 d-4 c-3 b,-4 a,-5 r

  %% Bar 5 — F
  c'8-3 e-2 f-1 g-2 a-1 c'-1 a-2 f-4

  %% Bar 6 — G
  d8-4 g-2 b-1 d'-1 b-2 g-3 e-2 d-1

  %% Bar 7 — E
  c8-3 e-1 gis-2 a-1 gis-2 e-3 d-4 b,-5

  %% Bar 8 — Am
  a'4-1 e'-3 a2-1
}

leftHandBeginner = \relative c, {
  \global
  \clef bass

  %% Bar 1 — Am
  a4-5 <c' e>-\markup { \finger "3 1" }
  a-5 <c e>-\markup { \finger "3 1" }

  %% Bar 2 — Dm
  d,-5 <a' d'>-\markup { \finger "3 1" }
  d,-5 <a' d'>-\markup { \finger "3 1" }

  %% Bar 3 — Am then E
  a4-5 <c' e>-\markup { \finger "3 1" }
  e,,-5 <b' e'>-\markup { \finger "3 1" }

  %% Bar 4 — Am then E
  a4-5 <c' e>-\markup { \finger "3 1" }
  e,,-5 <b' e'>-\markup { \finger "3 1" }

  %% Bar 5 — F
  f,4-5 <a' c'>-\markup { \finger "3 1" }
  f,-5 <a' c'>-\markup { \finger "3 1" }

  %% Bar 6 — G
  g,4-5 <b' d'>-\markup { \finger "3 1" }
  g,-5 <b' d'>-\markup { \finger "3 1" }

  %% Bar 7 — E
  e,4-5 <b' e'>-\markup { \finger "3 1" }
  e,-5 <b' e'>-\markup { \finger "3 1" }

  %% Bar 8 — Am
  a4-5 <c' e>-\markup { \finger "3 1" }
  a-5 <c e>\fermata-\markup { \finger "3 1" }
