\score {
  <<
    \new GrandStaff <<
      \new Staff {
        \melody
      }
      \new Staff {
        \leftHandBeginner
      }
    >>
  >>
  \layout {
    \context {
      \Score
      \override ChordName.font-size = #-1
    }
  }
  \midi { }
